-- Ensure all columns used by recurring payment INSERT exist
ALTER TABLE bookings.payments ADD COLUMN IF NOT EXISTS customer_id      UUID        REFERENCES bookings.customers(id);
ALTER TABLE bookings.payments ADD COLUMN IF NOT EXISTS tenant_id        INT;
ALTER TABLE bookings.payments ADD COLUMN IF NOT EXISTS payment_date     TIMESTAMPTZ DEFAULT NOW();
ALTER TABLE bookings.payments ADD COLUMN IF NOT EXISTS series_reference TEXT;

-- Index for fast lookup by tenant and series
CREATE INDEX IF NOT EXISTS idx_payments_tenant         ON bookings.payments(tenant_id);
CREATE INDEX IF NOT EXISTS idx_payments_customer       ON bookings.payments(customer_id) WHERE customer_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_payments_series_ref     ON bookings.payments(series_reference) WHERE series_reference IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_payments_type_tenant    ON bookings.payments(payment_type, tenant_id);
